<?php
require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../config/database.php';require_role('mahasiswa');
$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT k.*,m.nim,m.nama,m.prodi FROM krs k JOIN mahasiswa m ON m.id=k.mahasiswa_id WHERE k.id=? AND k.mahasiswa_id=?");$st->execute([$id,current_user()['profile_id']]);$k=$st->fetch();if(!$k)exit('Data KRS tidak ditemukan.');
$st=$pdo->prepare("SELECT mk.kode,mk.nama,mk.sks,j.kelas,j.hari,j.jam_mulai,j.jam_selesai,j.ruang,j.gedung FROM detail_krs d JOIN jadwal j ON j.id=d.jadwal_id JOIN mata_kuliah mk ON mk.id=j.mata_kuliah_id WHERE d.krs_id=?");$st->execute([$id]);$items=$st->fetchAll();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cetak KRS · WarKRS</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="print-body"><div class="print-actions"><a class="btn btn-ghost" href="krs.php">← Kembali</a><button class="btn btn-primary" onclick="window.print()">Cetak KRS</button></div><main class="print-sheet"><div class="print-brand">W<span>arKRS</span></div><h2>KARTU RENCANA STUDI</h2><p>UNIVERSITAS NEGERI MEDAN · PROTOTIPE SIMULASI</p><hr><div class="print-meta"><div><small>Nama</small><b><?= e($k['nama']) ?></b></div><div><small>NIM</small><b><?= e($k['nim']) ?></b></div><div><small>Program Studi</small><b><?= e($k['prodi']) ?></b></div><div><small>Tahun Akademik</small><b>2026/2027 Ganjil</b></div></div><table><thead><tr><th>No.</th><th>Kode</th><th>Mata Kuliah</th><th>SKS</th><th>Kelas</th><th>Hari</th><th>Waktu</th><th>Ruang</th><th>Gedung</th></tr></thead><tbody><?php foreach($items as $i=>$r): ?><tr><td><?= $i+1 ?></td><td><?= e($r['kode']) ?></td><td><?= e($r['nama']) ?></td><td><?= (int)$r['sks'] ?></td><td><?= e($r['kelas']) ?></td><td><?= e($r['hari']) ?></td><td><?= e(substr($r['jam_mulai'],0,5)) ?>–<?= e(substr($r['jam_selesai'],0,5)) ?></td><td><?= e($r['ruang']) ?></td><td><?= e($r['gedung']) ?></td></tr><?php endforeach; ?></tbody></table><div class="print-total"><b>Total SKS</b><strong><?= (int)$k['total_sks'] ?> SKS</strong><b>Status</b><strong><?= e($k['status']) ?></strong></div><div class="signature"><div>Mahasiswa</div><div>Dosen Wali</div></div><div class="print-note">Dokumen simulasi yang dihasilkan oleh aplikasi WarKRS.</div></main></body></html>
